mapper.select:
SELECT s.id, s.category_id, s.content, s.vector_id, s.source, s.quality_level,
       s.original_error_category, s.status, s.create_time,
       c.primary_category, c.sub_label
FROM rag_sample s
JOIN classify_category c ON c.id = s.category_id

    AND s.category_id = #{categoryId}
    AND s.source = #{source}
    AND s.quality_level = #{qualityLevel}
    AND s.status = #{status}

ORDER BY s.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(1)
FROM rag_sample s

    AND s.category_id = #{categoryId}
    AND s.source = #{source}
    AND s.quality_level = #{qualityLevel}
    AND s.status = #{status}

mapper.update:
UPDATE rag_sample
SET category_id = #{categoryId}, content = #{content}, vector_id = #{vectorId},
    source = #{source}, quality_level = #{qualityLevel},
    original_error_category = #{originalErrorCategory}, status = #{status}
WHERE id = #{id}
